  6→    <title>用户登录</title>
  7→    <script src="https://cdn.tailwindcss.com"></script>
  8→    <style>
  9→        /* shadcn/ui 风格变量模拟 */
 10→        :root {
 11→            --background: 0 0% 100%;
 12→            --foreground: 240 10% 3.9%;
 13→            --card: 0 0% 100%;
 14→            --card-foreground: 240 10% 3.9%;
 15→            --popover: 0 0% 100%;
 16→            --popover-foreground: 240 10% 3.9%;
 17→            --primary: 240 5.9% 10%;
 18→            --primary-foreground: 0 0% 98%;
 19→            --secondary: 240 4.8% 95.9%;
 20→            --secondary-foreground: 240 5.9% 10%;
 21→            --muted: 240 4.8% 95.9%;
 22→            --muted-foreground: 240 3.8% 46.1%;
 23→            --accent: 240 4.8% 95.9%;
 24→            --accent-foreground: 240 5.9% 10%;
 25→            --destructive: 0 84.2% 60.2%;
 26→            --destructive-foreground: 0 0% 98%;
 27→            --border: 240 5.9% 90%;
 28→            --input: 240 5.9% 90%;
 29→            --ring: 240 5.9% 10%;
 30→            --radius: 0.5rem;
 31→        }
 32→
 33→        .dark {
 34→            --background: 240 10% 3.9%;
 35→            --foreground: 0 0% 98%;
 36→            --card: 240 10% 3.9%;
 37→            --card-foreground: 0 0% 98%;
 38→            --popover: 240 10% 3.9%;
 39→            --popover-foreground: 0 0% 98%;
 40→            --primary: 0 0% 98%;
 41→            --primary-foreground: 240 5.9% 10%;
 42→            --secondary: 240 3.7% 15.9%;
 43→            --secondary-foreground: 0 0% 98%;
 44→            --muted: 240 3.7% 15.9%;
 45→            --muted-foreground: 240 5% 64.9%;
 46→            --accent: 240 3.7% 15.9%;
 47→            --accent-foreground: 0 0% 98%;
 48→            --destructive: 0 62.8% 30.6%;
 49→            --destructive-foreground: 0 0% 98%;
 50→            --border: 240 3.7% 15.9%;
 51→            --input: 240 3.7% 15.9%;
 52→            --ring: 240 4.9% 83.9%;
 53→        }
 54→
 55→        :root {
 56→            color-scheme: light;
 57→        }
 58→
 59→        .dark {
 60→            color-scheme: dark;
 61→        }
 62→
 63→        body {
 64→            font-family: ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
 65→            background-color: hsl(var(--background));
 66→            color: hsl(var(--foreground));
 67→        }
 68→
 69→        /* Skip Link for Accessibility */
 70→        .skip-link {
 71→            position: absolute;
 72→            top: -40px;
 73→            left: 0;
 74→            background: hsl(var(--primary));
 75→            color: hsl(var(--primary-foreground));
 76→            padding: 8px;
 77→            z-index: 100;
 78→            transition: top 0.2s;
 79→            border-radius: 0 0 var(--radius) 0;
 80→            font-weight: 500;
 81→        }
 82→        .skip-link:focus {
 83→            top: 0;
 84→        }
 85→
 86→        .shadcn-input {
 87→            background-color: hsl(var(--background));
 88→            border: 1px solid hsl(var(--input));
 89→            color: hsl(var(--foreground));
 90→            transition: border-color 0.2s, box-shadow 0.2s;
 91→        }
 92→
 93→        .shadcn-input:focus-visible {
 94→            outline: 2px solid transparent;
 95→            outline-offset: 2px;
 96→            box-shadow: 0 0 0 2px hsl(var(--background)), 0 0 0 4px hsl(var(--ring));
 97→            border-color: hsl(var(--ring));
 98→        }
 99→
100→        .shadcn-input:focus {
101→            outline: 2px solid transparent;
102→        }
103→
104→        .shadcn-input:disabled {
105→            cursor: not-allowed;
106→            opacity: 0.5;
107→        }
108→
109→        @media (prefers-reduced-motion: reduce) {
110→            .spinner {
111→                animation: none;
112→                border-top-color: white;
113→            }
114→            .skip-link {
115→                transition: none;
116→            }
117→        }
118→
119→        .shadcn-btn {
120→            transition: opacity 0.2s, background-color 0.2s, transform 0.1s, box-shadow 0.2s;
121→        }
122→        
123→        .shadcn-btn:hover:not(:disabled) {
124→            opacity: 0.9;
125→        }
126→        
127→        .shadcn-btn:active:not(:disabled) {
128→            transform: scale(0.98);
129→        }
130→
131→        .shadcn-checkbox {
132→            appearance: none;
133→            background-color: hsl(var(--background));
134→            border: 1px solid hsl(var(--input));
135→            width: 1rem;
136→            height: 1rem;
137→            border-radius: 0.25rem;
138→            display: grid;
139→            place-content: center;
140→            transition: background-color 0.2s, border-color 0.2s, box-shadow 0.2s;
141→        }
142→
143→        .shadcn-checkbox::before {
144→            content: "";
145→            width: 0.65em;
146→            height: 0.65em;
147→            transform: scale(0);
148→            transition: 120ms transform ease-in-out;
149→            box-shadow: inset 1em 1em hsl(var(--primary-foreground));
150→            transform-origin: center;
151→            clip-path: polygon(14% 44%, 0 65%, 50% 100%, 100% 16%, 80% 0%, 43% 62%);
152→        }
153→
154→        .shadcn-checkbox:checked::before {
155→            transform: scale(1);
156→        }
157→
158→        .shadcn-checkbox:focus-visible {
159→            outline: 2px solid transparent;
160→            outline-offset: 2px;
161→            box-shadow: 0 0 0 2px hsl(var(--background)), 0 0 0 4px hsl(var(--ring));
162→        }
163→
164→        .shadcn-checkbox:focus {
165→            outline: 2px solid transparent;
166→        }
167→
168→        /* 加载动画 */
169→        .spinner {
170→            border: 2px solid rgba(255, 255, 255, 0.3);
171→            border-radius: 50%;
172→            border-top: 2px solid white;
173→            width: 16px;
174→            height: 16px;
175→            animation: spin 1s linear infinite;
176→        }
177→
178→        @keyframes spin {
179→            0% { transform: rotate(0deg); }
180→            100% { transform: rotate(360deg); }
181→        }
182→
183→        /* 错误状态样式 */
184→        .input-error {
185→            border-color: hsl(var(--destructive)) !important;
186→        }
187→        .input-error:focus {
188→            box-shadow: 0 0 0 2px hsl(var(--background)), 0 0 0 4px hsl(var(--destructive)) !important;
189→        }
190→    </style>
191→    <script>
192→        // 简单的深色模式检测
193→        if (window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches) {
194→            document.documentElement.classList.add('dark');
195→        }
196→    </script>
197→</head>
198→<body class="min-h-screen flex items-center justify-center p-4">
199→    <a href="#main-content" class="skip-link">跳转到主要内容</a>
200→
201→    <div id="main-content" class="w-full max-w-[350px] space-y-6">
202→        <div class="flex flex-col space-y-2 text-center">
203→            <h1 class="text-2xl font-semibold tracking-tight text-balance">欢迎回来</h1>
204→            <p class="text-sm text-muted-foreground">
205→                请输入您的邮箱和密码以登录
206→            </p>
207→        </div>
208→
209→        <form id="loginForm" novalidate class="space-y-4">
210→            <div class="space-y-2">
211→                <label for="email" class="text-sm font-medium leading-none peer-disabled:cursor-not-allowed peer-disabled:opacity-70">邮箱</label>
212→                <input 
213→                    type="email" 
214→                    id="email" 
215→                    name="email"
216→                    autocomplete="email"
217→                    placeholder="name@example.com…" 
218→                    required
219→                    spellcheck="false"
220→                    class="shadcn-input flex h-9 w-full rounded-md border px-3 py-1 text-sm shadow-sm placeholder:text-muted-foreground disabled:cursor-not-allowed disabled:opacity-50"
221→                >
222→                <p id="emailError" role="alert" aria-live="polite" class="text-[0.8rem] font-medium text-destructive hidden">邮箱格式不正确，请检查后重试</p>
223→            </div>
224→
225→            <div class="space-y-2">
226→                <label for="password" class="text-sm font-medium leading-none peer-disabled:cursor-not-allowed peer-disabled:opacity-70">密码</label>
227→                <div class="relative">
228→                    <input 
229→                        type="password" 
230→                        id="password" 
231→                        name="password"
232→                        autocomplete="current-password"
233→                        placeholder="••••••••…" 
234→                        required
235→                        spellcheck="false"
236→                        class="shadcn-input flex h-9 w-full rounded-md border px-3 py-1 text-sm shadow-sm placeholder:text-muted-foreground disabled:cursor-not-allowed disabled:opacity-50 pr-10"
237→                    >
238→                    <button 
239→                        type="button" 
240→                        onclick="togglePassword()" 
241→                        onkeydown="if(event.key === 'Enter' || event.key === ' ') { event.preventDefault(); togglePassword(); }"
242→                        class="absolute right-3 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring rounded-sm touch-action-manipulation"
243→                        aria-label="切换密码可见性"
244→                        tabindex="0"
245→                    >
246→                        <svg id="eyeIcon" aria-hidden="true" xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M2 12s3-7 10-7 10 7 10 7-3 7-10 7-10-7-10-7Z"/><circle cx="12" cy="12" r="3"/></svg>
247→                        <svg id="eyeOffIcon" style="display: none;" aria-hidden="true" xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M9.88 9.88a3 3 0 1 0 4.24 4.24"/><path d="M10.73 5.08A10.43 10.43 0 0 1 12 5c7 0 10 7 10 7a13.16 13.16 0 0 1-1.67 2.68"/><path d="M6.61 6.61A13.526 13.526 0 0 0 2 12s3 7 10 7a9.74 9.74 0 0 0 5.39-1.61"/><line x1="2" x2="22" y1="2" y2="22"/></svg>
248→                    </button>
249→                </div>
250→                <p id="passwordError" role="alert" aria-live="polite" class="text-[0.8rem] font-medium text-destructive hidden">请输入您的密码</p>
251→            </div>
252→
253→            <div class="flex items-center justify-between pt-2">
254→                <label for="remember" class="flex items-center space-x-2 text-sm font-medium cursor-pointer select-none min-h-[2rem] py-1">
255→                    <input type="checkbox" id="remember" name="remember" class="shadcn-checkbox">
256→                    <span>记住我</span>
257→                </label>
258→                <a href="#" class="text-sm font-medium text-primary hover:underline underline-offset-4">
259→                    忘记密码？
260→                </a>
261→            </div>
262→
263→            <button 
264→                type="submit" 
265→                id="submitBtn"
266→                aria-busy="false"
267→                class="shadcn-btn inline-flex h-9 w-full items-center justify-center whitespace-nowrap rounded-md bg-primary px-4 py-2 text-sm font-medium text-primary-foreground shadow focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring disabled:pointer-events-none disabled:opacity-50"
268→            >
269→                <span id="btnText">登录</span>
270→                <div id="btnSpinner" class="spinner hidden ml-2" aria-hidden="true"></div>
271→            </button>
272→        </form>
273→
274→        <div class="text-center text-sm text-muted-foreground">
275→            还没有账号？
276→            <a href="#" class="text-primary hover:underline underline-offset-4 font-medium">
277→                立即注册
278→            </a>
279→        </div>
280→    </div>
281→
282→    <script>
283→        function togglePassword() {
284→            const passwordInput = document.getElementById('password');
285→            const eyeIcon = document.getElementById('eyeIcon');
286→            const eyeOffIcon = document.getElementById('eyeOffIcon');
287→            
288→            if (passwordInput.type === 'password') {
289→                passwordInput.type = 'text';
290→                eyeIcon.style.display = 'none';
291→                eyeOffIcon.style.display = 'block';
292→            } else {
293→                passwordInput.type = 'password';
294→                eyeIcon.style.display = 'block';
295→                eyeOffIcon.style.display = 'none';
296→            }
297→            passwordInput.focus();
298→        }
299→
300→        function validateEmail(email) {
301→            return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
302→        }
303→
304→        document.getElementById('loginForm').addEventListener('submit', function(e) {
305→            e.preventDefault();
306→            
307→            const emailInput = document.getElementById('email');
308→            const passwordInput = document.getElementById('password');
309→            const email = emailInput.value.trim();
310→            const password = passwordInput.value;
311→            const emailError = document.getElementById('emailError');
312→            const passwordError = document.getElementById('passwordError');
313→            let isValid = true;
314→
315→            // Reset styles
316→            emailInput.classList.remove('input-error');
317→            passwordInput.classList.remove('input-error');
318→
319→            if (!email || !validateEmail(email)) {
320→                emailError.classList.remove('hidden');
321→                emailInput.classList.add('input-error');
322→                isValid = false;
323→            } else {
324→                emailError.classList.add('hidden');
325→            }
326→
327→            if (!password) {
328→                passwordError.classList.remove('hidden');
329→                passwordInput.classList.add('input-error');
330→                isValid = false;
331→            } else {
332→                passwordError.classList.add('hidden');
333→            }
334→
335→            if (!isValid) return;
336→            
337→            const btn = document.getElementById('submitBtn');
338→            const btnText = document.getElementById('btnText');
339→            const btnSpinner = document.getElementById('btnSpinner');
340→            
341→            btn.disabled = true;
342→            btn.setAttribute('aria-busy', 'true');
343→            btnText.textContent = '登录中…';
344→            btnSpinner.classList.remove('hidden');
345→
346→            setTimeout(() => {
347→                btn.disabled = false;
348→                btn.setAttribute('aria-busy', 'false');
349→                btnText.textContent = '登录';
350→                btnSpinner.classList.add('hidden');
351→                alert(`登录成功！\n欢迎用户: ${email}`);
352→            }, 1500);
353→        });
354→
355→        document.getElementById('email').addEventListener('input', () => {
356→            document.getElementById('emailError').classList.add('hidden');
357→            document.getElementById('email').classList.remove('input-error');
358→        });
359→        document.getElementById('password').addEventListener('input', () => {
360→            document.getElementById('passwordError').classList.add('hidden');
361→            document.getElementById('password').classList.remove('input-error');
362→        });
363→    </script>
364→</body>
365→</html>

