369→    <script>
370→        function togglePassword() {
371→            const passwordInput = document.getElementById('password');
372→            const eyeIcon = document.getElementById('eyeIcon');
373→            const eyeOffIcon = document.getElementById('eyeOffIcon');
374→            
375→            if (passwordInput.type === 'password') {
376→                passwordInput.type = 'text';
377→                eyeIcon.style.display = 'none';
378→                eyeOffIcon.style.display = 'block';
379→            } else {
380→                passwordInput.type = 'password';
381→                eyeIcon.style.display = 'block';
382→                eyeOffIcon.style.display = 'none';
383→            }
384→            passwordInput.focus();
385→        }
386→
387→        function validateEmail(email) {
388→            return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
389→        }
390→
391→        document.getElementById('loginForm').addEventListener('submit', function(e) {
392→            e.preventDefault();
393→            
394→            const emailInput = document.getElementById('email');
395→            const passwordInput = document.getElementById('password');
396→            const email = emailInput.value.trim();
397→            const password = passwordInput.value;
398→            const emailError = document.getElementById('emailError');
399→            const passwordError = document.getElementById('passwordError');
400→            let isValid = true;
401→
402→            // Reset styles
403→            emailInput.classList.remove('input-error');
404→            passwordInput.classList.remove('input-error');
405→
406→            if (!email || !validateEmail(email)) {
407→                emailError.classList.remove('hidden');
408→                emailInput.classList.add('input-error');
409→                isValid = false;
410→            } else {
411→                emailError.classList.add('hidden');
412→            }
413→
414→            if (!password) {
415→                passwordError.classList.remove('hidden');
416→                passwordInput.classList.add('input-error');
417→                isValid = false;
418→            } else {
419→                passwordError.classList.add('hidden');
420→            }
421→
422→            if (!isValid) return;
423→            
424→            const btn = document.getElementById('submitBtn');
425→            const btnText = document.getElementById('btnText');
426→            const btnSpinner = document.getElementById('btnSpinner');
427→            
428→            btn.disabled = true;
429→            btn.setAttribute('aria-busy', 'true');
430→            btnText.textContent = '登录中…';
431→            btnSpinner.classList.remove('hidden');
432→
433→            setTimeout(() => {
434→                btn.disabled = false;
435→                btn.setAttribute('aria-busy', 'false');
436→                btnText.textContent = '登录';
437→                btnSpinner.classList.add('hidden');
438→                alert(`登录成功！\n欢迎用户: ${email}`);
439→            }, 1500);
440→        });
441→
442→        document.getElementById('email').addEventListener('input', () => {
443→            document.getElementById('emailError').classList.add('hidden');
444→            document.getElementById('email').classList.remove('input-error');
445→        });
446→        document.getElementById('password').addEventListener('input', () => {
447→            document.getElementById('passwordError').classList.add('hidden');
448→            document.getElementById('password').classList.remove('input-error');
449→        });
450→    </script>
451→</body>
